import json
import re
from pathlib import Path
from typing import Dict, List, Tuple

HEADER_RE = re.compile(r"^\[(.+)\]\s*$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.+?)\s*->\s*(\S+)\s*$")
LINE_RE = re.compile(r"^\s*([^:]+):\s*(.+?)\s*->\s*(\S+)\s*$")


def _parse_block(node_id: str, lines: List[str]) -> Tuple[Dict[str, str], List[Dict[str, str]]]:
    choices: List[Tuple[str, str]] = []
    dialogue: List[Tuple[str, str, str]] = []

    for raw in lines:
        if not raw.strip():
            continue
        choice_match = CHOICE_RE.match(raw)
        if choice_match:
            text, target = choice_match.group(1).strip(), choice_match.group(2).strip()
            choices.append((text, target))
            continue
        line_match = LINE_RE.match(raw)
        if line_match:
            speaker = line_match.group(1).strip()
            text = line_match.group(2).strip()
            target = line_match.group(3).strip()
            dialogue.append((speaker, text, target))
            continue
        raise ValueError(f"Unrecognized line in [{node_id}]: {raw}")

    if choices and dialogue:
        raise ValueError(f"Mixed choice and dialogue lines in [{node_id}]")
    if choices:
        node = {"id": node_id, "text": "", "speaker": "", "type": "choice"}
        edges = [{"from": node_id, "to": target, "text": text} for text, target in choices]
        return node, edges
    if dialogue:
        if len(dialogue) != 1:
            raise ValueError(f"Expected a single dialogue line in [{node_id}], got {len(dialogue)}")
        speaker, text, target = dialogue[0]
        node = {"id": node_id, "text": text, "speaker": speaker, "type": "line"}
        edges = [{"from": node_id, "to": target, "text": ""}]
        return node, edges

    raise ValueError(f"Empty block for [{node_id}]")


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    current_id = None
    current_lines: List[str] = []

    def flush() -> None:
        nonlocal current_id, current_lines, nodes, edges
        if current_id is None:
            return
        node, new_edges = _parse_block(current_id, current_lines)
        nodes.append(node)
        edges.extend(new_edges)
        current_id = None
        current_lines = []

    for raw_line in text.splitlines():
        header_match = HEADER_RE.match(raw_line.strip())
        if header_match:
            flush()
            current_id = header_match.group(1).strip()
            current_lines = []
            continue
        if current_id is None:
            if raw_line.strip():
                raise ValueError(f"Line outside any node: {raw_line}")
            continue
        current_lines.append(raw_line)

    flush()

    node_ids = {n["id"] for n in nodes}
    if "End" not in node_ids and any(e["to"] == "End" for e in edges):
        nodes.append({"id": "End", "text": "End", "speaker": "", "type": "line"})
        node_ids.add("End")

    _validate_graph(nodes, edges)
    return {"nodes": nodes, "edges": edges}


def _validate_graph(nodes: List[Dict[str, str]], edges: List[Dict[str, str]]) -> None:
    if not nodes:
        raise ValueError("No nodes parsed")

    node_ids = {n["id"] for n in nodes}
    for edge in edges:
        target = edge["to"]
        if target not in node_ids:
            raise ValueError(f"Edge target does not exist: {target}")

    start_id = nodes[0]["id"]
    adjacency = {node_id: [] for node_id in node_ids}
    for edge in edges:
        if edge["from"] in adjacency:
            adjacency[edge["from"]].append(edge["to"])

    seen = set()
    stack = [start_id]
    while stack:
        current = stack.pop()
        if current in seen:
            continue
        seen.add(current)
        for nxt in adjacency.get(current, []):
            if nxt not in seen:
                stack.append(nxt)

    unreachable = node_ids - seen
    if unreachable:
        raise ValueError(f"Unreachable nodes from start [{start_id}]: {sorted(unreachable)}")


def _escape_dot(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", " ")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;"]
    for node in graph["nodes"]:
        node_id = _escape_dot(node["id"])
        if node["type"] == "choice":
            label = f"{node['id']} (choice)"
        else:
            speaker = node.get("speaker", "").strip()
            text = node.get("text", "").strip()
            label = f"{speaker}: {text}".strip(": ") or node["id"]
        lines.append(f'  "{node_id}" [label="{_escape_dot(label)}"];')
    for edge in graph["edges"]:
        src = _escape_dot(edge["from"])
        dst = _escape_dot(edge["to"])
        label = _escape_dot(edge.get("text", ""))
        if label:
            lines.append(f'  "{src}" -> "{dst}" [label="{label}"];')
        else:
            lines.append(f'  "{src}" -> "{dst}";')
    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    script_path = Path("/app/script.txt")
    output_json = Path("/app/dialogue.json")
    output_dot = Path("/app/dialogue.dot")

    text = script_path.read_text(encoding="utf-8")
    graph = parse_script(text)

    output_json.write_text(json.dumps(graph, indent=2), encoding="utf-8")
    output_dot.write_text(graph_to_dot(graph), encoding="utf-8")


if __name__ == "__main__":
    main()
